const avatarStylesList = ['bottts', 'avataaars', 'adventurer', 'micah', 'pixel-art'];
window.cambiarEstiloAvatar = async function() { let idx = avatarStylesList.indexOf(window.userProfile.avatarStyle || 'bottts'); window.userProfile.avatarStyle = avatarStylesList[(idx + 1) % avatarStylesList.length]; await window.guardarEstadoNube(); window.actualizarUIHeader(); window.actualizarUIPerfil(); window.showToast("🎲 Estilo actualizado."); };

